static uint32_t __stdcall SFILE_FindFileOnDisk(uint8_t bSearchFlags, LPCSTR szOutPath, char * szFileName) {
    uint32_t dwFileAttributes = 0;
    if (!(bSearchFlags & 3)) {
      return dwFileAttributes;
    }
    if (bSearchFlags & 2) {
      SFILE_ConvertRelativePathName(1, szFileName, (char*)szOutPath);
      dwFileAttributes = SFILE_FileExistsOnDisk(szOutPath);
      if (dwFileAttributes) {
        return dwFileAttributes;
      }
    }

    dwFileAttributes = 0;
    if (!(bSearchFlags & 1)) {
      return dwFileAttributes;
    }
    if (*szFileName != '\\') {
      char* pFound;
      pFound = strstr(szFileName, ":\\");
      if (!pFound) {
        pFound = strstr(szFileName, "\\\\");
        if (!pFound) {
          SFILE_ConvertRelativePathName(0, szFileName, (char*)szOutPath);
          dwFileAttributes = SFILE_FileExistsOnDisk(szOutPath);
          return dwFileAttributes;
        }
      }
    }

    SSTR::SStrCopy((char*)szOutPath, szFileName, 0x104);
    dwFileAttributes = SFILE_FileExistsOnDisk(szOutPath);
    return dwFileAttributes;
}

